<script setup lang="ts">
import { ref } from 'vue'
import { useRoute } from 'vue-router'
import type { StudentDetail, Lesson, Page, Credit, Wallet, Kind } from '../api/types'
import { write } from '../api/client'
import { useResource, useAction } from '../lib/useResource'
import { date, kinds } from '../lib/format'
import WalletSummary from '../components/WalletSummary.vue'
import LessonList from '../components/LessonList.vue'
import ResourceState from '../components/ResourceState.vue'
import FormFeedback from '../components/FormFeedback.vue'
import Field from '../components/Field.vue'
import Pagination from '../components/Pagination.vue'
import CreatePlan from '../components/CreatePlan.vue'
const route=useRoute(),page=ref(1),creditPage=ref(1)
const {data,error:loadError,loading,refresh}=useResource<StudentDetail>(() => `/api/v1/coach/students/${route.params.id}/`)
const history=useResource<Page<Lesson>>(() => `/api/v1/coach/lessons/?student_id=${route.params.id}&page=${page.value}`)
const credits=useResource<Page<Credit>>(() => `/api/v1/coach/students/${route.params.id}/credits/?page=${creditPage.value}`)
const kind=ref<Kind>('private'),units=ref<number | null>(null),adding=ref(false),invite=ref(''),expiresOn=ref('')
let operationKey=crypto.randomUUID()
function newCreditKey(){operationKey=crypto.randomUUID()}
const {busy,error,notice,run}=useAction()
async function addCredits(){const result=await run(() => write<{wallets:Wallet[]}>(`/api/v1/coach/students/${route.params.id}/credits/`,{kind:kind.value,units:units.value,operation_key:operationKey,expires_on:expiresOn.value || null}),'续课已录入，课包已更新。');if(result){operationKey=crypto.randomUUID();units.value=null;expiresOn.value='';adding.value=false;await refresh();await credits.refresh()}}
async function issueInvite(){const result=await run(() => write<{url:string}>(`/api/v1/coach/students/${route.params.id}/invitations/`));if(result)invite.value=result.url}
async function copyInvite(){try{await navigator.clipboard.writeText(invite.value);notice.value='邀请链接已复制。'}catch{notice.value='请选中下方链接复制。'}}
</script>
<template><RouterLink class="back-link" to="/coach/students/">返回学员</RouterLink><ResourceState :error="loadError" :loading="loading && !data" @retry="refresh" /><template v-if="data"><div class="page-heading"><div><h1>{{ data.student.name }}</h1><p>{{ data.student.registered ? '账号已绑定，学员可以查看自己的课包与记录。' : '档案已创建，可以先记课，再邀请学员加入。' }}</p></div><RouterLink class="button primary" :to="`/coach/lessons/new/?student=${data.student.id}`">记一节课</RouterLink></div><WalletSummary :wallets="data.wallets" /><div class="actions"><button class="button secondary" @click="adding=!adding">录入续课</button><button v-if="!data.student.registered" class="button secondary" :disabled="busy" @click="issueInvite">生成邀请链接</button></div><FormFeedback :error="error" :notice="notice" /><div v-if="invite" class="surface copy-row"><label class="field"><span class="field-label">邀请链接 · 7天有效</span><input :value="invite" readonly @focus="($event.target as HTMLInputElement).select()" /></label><button class="button secondary" @click="copyInvite">复制链接</button></div><form v-if="adding" class="surface stack-form compact-form" @submit.prevent="addCredits"><h2>录入实际购买的课时</h2><div class="form-grid"><Field label="课包类型"><select v-model="kind" @change="newCreditKey"><option value="private">一对一私教</option><option value="group">小班课</option></select></Field><Field label="新增次数" :errors="error?.fields.units"><input v-model.number="units" type="number" min="1" max="10000" step="1" required @change="newCreditKey" /></Field><Field label="到期日（选填）" hint="留空为长期有效；到期日当天仍可用。" :errors="error?.fields.expires_on"><input v-model="expiresOn" type="date" :disabled="busy" @change="newCreditKey" /></Field></div><button class="button primary" :disabled="busy">{{ busy ? '正在录入…' : '确认录入' }}</button></form><section class="section"><div class="section-heading"><h2>本月到课记录</h2><span>{{ data.attendance.period }}</span></div><div class="attendance-summary"><span>预约到课 <strong>{{ data.attendance.scheduled_attended }}</strong> 次</span><span>直接记课 <strong>{{ data.attendance.direct_attended }}</strong> 次</span><span>缺席 <strong>{{ data.attendance.scheduled_missed }}</strong> 次</span><span>取消 <strong>{{ data.attendance.scheduled_cancelled }}</strong> 次</span><span>待确认 <strong>{{ data.attendance.pending }}</strong> 次</span></div><p class="hint">预约到课率：{{ data.attendance.scheduled_rate===null ? '暂无已确认出勤' : `${data.attendance.scheduled_rate}%` }}。仅按已处理预约统计，直接记课单独计数。</p></section><section class="section"><div class="section-heading"><h2>上课历史</h2></div><ResourceState :error="history.error.value" :loading="history.loading.value" @retry="history.refresh" /><div v-if="history.data.value" class="surface list-surface"><LessonList :items="history.data.value.items" coach /></div><Pagination v-if="history.data.value" :page="page" :page-size="history.data.value.pagination.page_size" :total="history.data.value.pagination.total" @change="page=$event" /></section><details class="secondary-section"><summary>课时流水</summary><ResourceState :error="credits.error.value" @retry="credits.refresh" /><div v-if="credits.data.value" class="ledger"><div v-for="entry in credits.data.value.items" :key="entry.id" class="ledger-row"><div class="grow"><h3>{{ entry.title }}</h3><p>{{ kinds[entry.kind] }} · {{ date(entry.created_at) }}<template v-if="entry.entry_type==='purchase'"> · {{entry.expires_on ? `${date(entry.expires_on)} 到期` : '长期有效'}}</template></p></div><strong :class="entry.entry_type==='purchase' ? 'positive' : ''">{{ entry.entry_type==='purchase' ? '+' : '−' }}{{ entry.units }} 次</strong></div><p v-if="!credits.data.value.items.length" class="empty-note">还没有课时流水。</p><Pagination :page="creditPage" :page-size="credits.data.value.pagination.page_size" :total="credits.data.value.pagination.total" @change="creditPage=$event" /></div></details><details class="secondary-section"><summary>布置课后练习（按需使用）</summary><CreatePlan :student-id="data.student.id" /></details></template></template>
